# %% [markdown]
# ## Step 2 — Define the Bug-Fix Evaluation Domain
#
# We're building an evaluation harness for a **code bug-fix agent**. The agent takes buggy code and generates two candidate fixes. Our job: score both candidates using an LLM judge with a rubric tailored to bug fixes.
#
# First, let's define the data structures: a test case (buggy code + reference fix), and a score (criterion + score + reasoning).

# %%
import json, time, hashlib
from dataclasses import dataclass, field
from typing import Optional

@dataclass
class CodeTestCase:
    """A test case for code bug-fix evaluation."""
    buggy_code: str
    reference_fix: str
    bug_description: str
    category: str = "general"
    id: str = ""

    def __post_init__(self):
        if not self.id:
            self.id = hashlib.md5(self.buggy_code.encode()).hexdigest()[:8]

@dataclass
class EvalScore:
    """A single evaluation score for one criterion."""
    criterion: str
    score: int
    reasoning: str
    max_score: int = 5

@dataclass
class CodeEvalResult:
    """Results from evaluating one code fix against the rubric."""
    test_case_id: str
    generated_fix: str
    scores: list  # List of EvalScore
    model: str = "judge"
    timestamp: float = 0.0

    def __post_init__(self):
        if not self.timestamp:
            self.timestamp = time.time()

    def average_score(self):
        if not self.scores:
            return 0.0
        return sum(s.score for s in self.scores) / len(self.scores)

print("✅ Data structures defined: CodeTestCase, EvalScore, CodeEvalResult")

# %% [markdown]
# ## Step 3 — Define the Rubric for Code Quality
#
# A good rubric anchors each score to specific, observable behaviors. For code fixes, we evaluate on 4 criteria:
# - **Correctness**: Does the fix actually solve the bug?
# - **Completeness**: Does it handle all edge cases?
# - **Code Quality**: Is the code readable, efficient, and maintainable?
# - **Safety**: Does it avoid introducing new bugs or security issues?

# %%
RUBRIC = {
    "correctness": {
        5: "The fix completely solves the stated bug. All test cases pass. No logical errors.",
        4: "The fix solves the main bug but may have minor issues that don't affect typical use.",
        3: "The fix addresses the bug partially. Some edge cases still fail.",
        2: "The fix attempts to address the bug but fails on most test cases.",
        1: "The fix is incorrect or makes the bug worse.",
    },
    "completeness": {
        5: "Handles all edge cases, boundary conditions, and error scenarios mentioned in the bug report.",
        4: "Handles most edge cases; misses one minor case.",
        3: "Handles the main case but misses multiple edge cases or error conditions.",
        2: "Incomplete solution; significant gaps in coverage.",
        1: "Very incomplete; does not address the core requirement.",
    },
    "code_quality": {
        5: "Code is clean, readable, well-structured, and efficient. Follows best practices.",
        4: "Code is generally good but could be more efficient or readable in places.",
        3: "Code works but is somewhat unclear or inefficient.",
        2: "Code is hard to read or has performance issues.",
        1: "Code is messy, unreadable, or extremely inefficient.",
    },
    "safety": {
        5: "No new bugs introduced. No security issues. Maintains backwards compatibility.",
        4: "No critical issues but may have minor edge cases that could cause problems.",
        3: "May introduce minor bugs in rare scenarios.",
        2: "Introduces a noticeable bug or security concern.",
        1: "Introduces critical bugs or security vulnerabilities.",
    },
}

print("✅ Rubric defined with 4 criteria:")
for criterion in RUBRIC.keys():
    print(f"  - {criterion}")

