# %% [markdown]
# ## Step 5 — Score a Fix Using LLM-as-Judge
#
# Now we'll use the LLM judge to score a candidate fix against our rubric. We send:
# 1. The buggy code (what we're trying to fix)
# 2. The reference fix (what a good fix looks like)
# 3. The candidate fix (what the agent generated)
# 4. The rubric (scoring criteria)
#
# The judge returns scores and reasoning for each criterion.

# %%
async def score_candidate_fix(buggy_code, reference_fix, candidate_fix):
    """Use LLM-as-judge to score a candidate fix against the rubric."""
    
    prompt = f"""You are an expert code reviewer evaluating a bug fix.

BUGGY CODE:
```
{buggy_code}
```

REFERENCE FIX (what a correct fix looks like):
```
{reference_fix}
```

CANDIDATE FIX (the fix we're evaluating):
```
{candidate_fix}
```

Score this candidate fix on the following criteria. For each, respond with a number 1-5 and one sentence of reasoning.

CRITERIA:
1. Correctness (1-5): Does the fix solve the bug? Are there logical errors?
2. Completeness (1-5): Does it handle edge cases?
3. Code Quality (1-5): Is it readable, efficient, and maintainable?
4. Safety (1-5): Does it avoid introducing new bugs?

Respond in JSON format:
{{"correctness": {{"score": <1-5>, "reasoning": "..."}}, "completeness": {{"score": <1-5>, "reasoning": "..."}}, "code_quality": {{"score": <1-5>, "reasoning": "..."}}, "safety": {{"score": <1-5>, "reasoning": "..."}}}}\n"""
    
    resp = await lrn_llm.call([{"role": "user", "content": prompt}], max_tokens=500)
    text = lrn_llm.text(resp)
    
    # Parse JSON response
    try:
        import json as json_lib
        scores_data = json_lib.loads(text)
    except:
        # Fallback if JSON parsing fails
        scores_data = {
            "correctness": {"score": 3, "reasoning": "Could not parse judge response"},
            "completeness": {"score": 3, "reasoning": "Could not parse judge response"},
            "code_quality": {"score": 3, "reasoning": "Could not parse judge response"},
            "safety": {"score": 3, "reasoning": "Could not parse judge response"},
        }
    
    scores = []
    for criterion, data in scores_data.items():
        scores.append(EvalScore(
            criterion=criterion.replace("_", " "),
            score=data["score"],
            reasoning=data["reasoning"],
        ))
    return scores

print("✅ Judge function defined")

