print(f"\nCandidate #2 (built-in): {avg_2:.2f}/5")
for s in scores_2:
    print(f"  {s.criterion:.<20} {s.score}/5")

print("\n" + "="*60)
if avg_1 > avg_2:
    winner = "Candidate #1 (loop-based)"
    diff = avg_1 - avg_2
elif avg_2 > avg_1:
    winner = "Candidate #2 (built-in)"
    diff = avg_2 - avg_1
else:
    winner = "TIE"
    diff = 0

print(f"Winner: {winner}")
if diff > 0:
    print(f"Difference: +{diff:.2f} points")
print("\nDecision: SHIP the higher-scoring candidate")

